TYPES = [
	["Muinasmaakond", "Muinasmaakonnad"],
	["Rahvus", "Rahvused"],
	["Linn", "Linnad"],
	["Valdus", "Valdused"],
	["Valitseja ametinimetus", "Valitseja ametinimetused"]
],
SETUP = {
	path: "/", // path to root folder of this web app
	timeCodeLen: 3 // how many b36 digits are used to encode time taken
},
ZD = (new Date(0)).toUTCString();

// get element by id "macro"
e = document.getElementById.bind(document),

// get all cookies
allCookies = () => { return document.cookie.split(";"); },

setCookie = (k, v) => {
	// expire after roughly 3 months
	document.cookie = `${k}=${v}; path=${SETUP.path}; SameSite=Strict; Secure; expires=${(new Date(Date.now()+8e9)).toUTCString()}`;
},

getCookie = (k) => {
	k += "=";

	const
	a = allCookies(),
	l = a.length;

	for (let i = 0; i < l; i++) {
		let c = a[i].trimStart();

		if (c.indexOf(k) == 0) {
			return c.substring(k.length);
		}
	}

	return null;
},

// remove all cookies
clearAll = () => {
	const
	a = allCookies(),
	l = a.length;

	for (let i = 0; i < l; i++) {
		document.cookie = `${a[i]}=;expires=${ZD}`;
	}
},

tCookie = (el) => {
	conf.cookies = el.checked ?? false;

	if (conf.cookies) {
		saveConf();
	} else {
		clearAll();
	}
},

// string normalization functions
// 2case + 1diac
snf = [
	(s) => { return s.toLowerCase().normalize("NFKD").replace(/[^\p{L}]/gu, ""); },			// cd
	(s) => { return s.toLowerCase().replace(/[^\p{L}]/gu, ""); },							// cD
	(s) => { return s.normalize("NFKD").replace(/[^\p{L}]/gu, ""); },						// Cd
	(s) => { return s.replace(/[^\p{L}]/gu, ""); },											// CD
],

// get the translation code for a given position,
// accounting for some differences
getTrns = (x, y, scl) => {
	const
	sm = 100*(1 - scl),
	nx = Math.min(Math.max(50-(scl*x), sm), 0),
	ny = Math.min(Math.max(50-(scl*y), sm), 0);
	return `${nx}% ${ny}%`;
},

// key down
keyD = (event) => {
	switch (event.key) {
		case "F8":
			mapDisp(1);
			return;

		case "F2":
			prev();
			return;
	}

	if (cv.active != 1) {
		if (event.key == "F4") {
			start();
		}

		return;
	}

	switch (event.key) {
		case "ArrowUp":
			ci(1);
			break;

		case "ArrowDown":
			ci(-1);
			break;

		case "Enter":
			reveal();
			break;

		case "ArrowLeft":
			if (EL_AW === document.activeElement) {
				if (EL_AW.value == "") {
					ci(-1);
				}
			} else {
				topBar(1);
				EL_AW.focus();
			}
			break;

		case "ArrowRight":
			if (EL_AW === document.activeElement) {
				if (EL_AW.value == "") {
					ci(1);
				}
			} else {
				topBar(1);
				EL_AW.focus();
			}
			break;

		case "F4":
			end();
	}
},

// show the n-th top bar
topBar = (n) => {
	for (let i = 0; i < 4; i++) {
		e(`t${i}`).style.display = i==n ? "" : "none";
	}

	if (n>0) {
		e("sel").style.display = "none";
	} else {
		e("sel").style.display = "";
	}
},

// change the map display setting
mapDisp = (n) => {
	conf.mapDisplay = Math.round(conf.mapDisplay + n);
	if (conf.mapDisplay < 0) {
		conf.mapDisplay = 3;
	} else if (conf.mapDisplay > 3) {
		conf.mapDisplay = 0;
	}

	const c = e("d");

	["w", "h", "f"].forEach((k, i) => {
		if (conf.mapDisplay == i) {
			c.classList.add(k);
		} else {
			c.classList.remove(k);
		}
	});

	e("sz").innerText = ["Paigutus: \u2194", "Paigutus: \u2195", "Paigutus: \u2b1c", "Suum"][conf.mapDisplay];

	const d = e("c");

	if (conf.mapDisplay == 3) {
		c.classList.add("f");
	}

	if (conf.mapDisplay == 3 && cv.active>0) { // if zoom selected
		const o = OBJ_DATA[cv.abs];
		d.style.translate = getTrns(o.x, o.y, conf.zoom);
		d.style.scale = conf.zoom;
		document.body.style.overflow = "clip";
	} else {
		d.style.translate = "";
		d.style.scale = "";
		document.body.style.overflow = "";
	}

},

// open or close the configuration page
config = (s = 1) => {
	e("conf").style.display = ["none",""][s];
},

// increment the count of answered objects
// and update the display
icounter = () => {
	e("ct").innerText = cv.ans++ +1;
	e("ca").innerText = cg.total;
},

// change the index of the current object to answer
ci = (n) => {
	cv.idx = Math.round(cv.idx + n);
	const l = cv.ixx.length;

	if (l==0) {
		end();
		return;
	}

	if (cv.idx < 0) {
		cv.idx = l - 1;
	} else if (cv.idx >= l) {
		cv.idx = 0;
	}

	cv.sans[cv.abs] = EL_AW.value;
	hilight(cv.abs = cv.ixx[cv.idx]);

	if (cv.guess[cv.abs] === null) {
		EL_AW.placeholder = OBJ_DATA[cv.abs].names[0][1];
	} else /*if (OBJ_DATA[cv.abs].duplicate)*/ {
		EL_AW.placeholder = TYPES[OBJ_DATA[cv.abs].type][0];
	} /*else {
		EL_AW.placeholder = "Vastus";
	}*/

	cv.abs = cv.ixx[cv.idx];

	const s = cv.sans[cv.abs];
	EL_AW.value = s;

	ansW();
},

start = (a = conf.selected) => {
	if (a.length < 1) {
		return;
	}

	let m = [];
	cv.result = new Array(OBJ_DATA.length).fill(5);

	a.forEach((k, i) => {
		if (k) {
			m.splice(Math.random()*(m.length+1), 0, i);
			cv.result[i] = 4;
		}
	});

	e("c").innerHTML = MAP_SRC;

	if (conf.mapDisplay == 3) {
		e("c").style.scale = conf.zoom;
	}

	cg.total = m.length, // total number of objects in this round
	cg.rdiac = e("wd").checked,
	cg.rcase = e("wc").checked,
	cg.stime = Date.now(), // start time
	cv.active = 1, // if the game is ongoing, 0=no, 1=yes, 2=preview
	cv.sans = new Array(OBJ_DATA.length).fill(""), // saved answers that had been inputted into the answer text box
	cv.idx = 0, // index of the current object that the user has to guess (in the ixx array)
	cv.abs = null, // index of the current object that the user has to guess (in the OBJ_DATA array)
	cv.ans = -1, // how many objects the user has answered (ordered like OBJ_DATA)
	cv.guess = Array.from({ length: OBJ_DATA.length }, () => []), // wrong guesses (ordered like OBJ_DATA)
	cv.ixx = m, // which objects are not answered yet
	nsg = snf[2*cg.rcase + cg.rdiac];

	icounter();

	ANS = [];

	OBJ_DATA.forEach((m, i) => {
		let kn = [];

		m.names.forEach(k => {
			const
			b = nsg(k[0]),
			f = nsg(k[1]);

			if (!kn.includes(f)) {
				ANS.push({
					str: f,
					idx: i
				});

				kn.push(f);
			}

			if (!(cg.rtyp || kn.includes(b))) {
				ANS.push({
					str: b,
					idx: i
				});

				kn.push(b);
			}
			
		});
	});

	topBar(1);
	ci(0);
	ansW();
	mapDisp(0);
},

prev = () => {
	topBar(3);

	cv.active = 2;
	cv.idx = 0;
	cv.abs = 0;
	cv.ixx = new Array(OBJ_SRC.length).keys();

	e("c").innerHTML = MAP_SRC;

	if (conf.mapDisplay == 3) {
		e("c").style.scale = conf.zoom;
	}

	document.addEventListener("keydown", prevKeyD);

	mapDisp(0);

	preview();
},

prevEnd = () => {
	cv.active = 0;
	document.removeEventListener("keydown", prevKeyD);
	topBar(0);
	mapDisp(0);
	hilight(-1);
},

prevKeyD = (event, ovr) => {
	const l = OBJ_DATA.length;

	if (event === null) {
		event = {key: ovr};
	}

	switch (event.key) {
		case "ArrowLeft":
		case "ArrowDown":
			cv.idx = Math.round(cv.idx - 1);
			if (cv.idx < 0) { cv.idx = l - 1; }
			cv.abs = cv.idx;
			preview();
			break;

		case "ArrowRight":
		case "ArrowUp":
			cv.idx = Math.round(cv.idx + 1);
			if (cv.idx >= l) { cv.idx = 0; }
			cv.abs = cv.idx;
			preview();
			break;
		
		case "F4":
			prevEnd();
			break;

	}
},

preview = () => {
	hilight(cv.idx);
	e("di").innerText = `${cv.idx + 1}: ${
		OBJ_DATA[cv.idx].names.map(k => { return k[1]; }).join(" / ")
	}`;
},

end = () => {
	e("c").style.translate = "";
	e("c").style.scale = "";
	cv.active = 0;
	cv.ixx.forEach(k => {
		addName(k, 4);
	});
	hilight(-1);
	topBar(0);
	mapDisp(0);
},

// process written answer
ansW = () => {
	const
	l = ANS.length,
	v = nsg(EL_AW.value);

	let wr = false; // has a wrong answer been entered?
	
	for (let i = 0; i < l; i++) {
		const
		idx = ANS[i].idx,
		str = ANS[i].str;

		if (idx == cv.abs) { // if this index has the correct answer
			if (v == str) { // has the correct answer been entered?

				const
				g = cv.guess[idx], // guesses
				a = g===null ?
					3
					: [0, 1, 2, 2, 3][Math.min(g.length, 4)];
				addName(idx, a);
				EL_AW.animate(correctAnim, correctTiming);
				cv.ixx.splice(cv.idx, 1);
				icounter();
				ci(0);
				return;
			}

			if (str.substring(0, v.length) == v) { // if the correct answer has been patially entered
				wr = null;
			}
		}

		if ((wr !== null) && (v == ANS[i].str)) { // wrong answer
			wr = idx;
		}
	}

	if (wr===false || wr===null) {
		// no matching answer
		EL_AW.classList.remove("w");
	} else {
		// wrong answer
		EL_AW.classList.add("w");
		if (!cv.guess[cv.abs].includes(wr)) {
			cv.guess[cv.abs].push(wr);
		}
	}
},

reveal = () => {
	cv.guess[cv.abs] = null;
	EL_AW.value = "";
	ci(0);
},

hilight = (n) => {
	try { e("h").remove(); } catch (err) {}

	if (n < 0) {
		return;
	}

	const
	o = OBJ_DATA[n];

	let d = o.path;

	if (typeof d === "number") {
		d = OBJ_DATA[d].path
	}

	const p = document.createElementNS("http://www.w3.org/2000/svg", "path");
	p.id = "h";

	p.classList.add("h");
	if (d[d.length-1].toLowerCase() == "z") {
		p.classList.add("z");
	}

	p.setAttribute("d", Number.isInteger(d) ? OBJ_DATA[d].path : d);
	e("m").appendChild(p);
	if (conf.mapDisplay == 3) {
		e("c").style.translate = getTrns(o.x, o.y, conf.zoom);
	}
},

addName = (n, c) => {
	const
	p = document.createElement("p"),
	o = OBJ_DATA[n];

	p.style = `left:${o.x}%;top:${o.y}%`;

	p.classList.add("gyor"[c]);

	p.innerText = o.names[0][1];
	e("c").appendChild(p);
	return p;
},

selGr = (s = false) => {
	const f =
		s	? m => { e(`s${m}`).classList.add("s");		conf.selected[m] = true; }
			: m => { e(`s${m}`).classList.remove("s");	conf.selected[m] = false; };

	for (let i = 0; i < OBJ_DATA.length; i++) {
		f(i);
	}

	saveConf();
},

// change the selection state of one object
sel = (ev) => {
	const
	n = ev.target.dataset.i,
	s = !(conf.selected[n]??true),
	m = ev.target.classList;

	conf.selected[n] = s;

	if (s) {
		m.add("s");
	} else {
		m.remove("s");
	}

	saveConf();
},

saveConf = () => {
	if (!conf.cookies) {
		return;
	}

	let
	s = "",
	n = 0,
	i = 4;

	for (let k of conf.selected) {
		n = k ? (n | 1<<i) : n;

		if (i==0) {
			s += n.toString(32);
			n = 0;
			i = 4;
		} else {
			i--;
		}
	}

	if (i != 4) {
		s += n.toString(32);
	}

	s += conf.mapDisplay.toString();

	setCookie("s", s);

	setCookie("o", `${(e("wd").checked??false)?"1":"0"}${(e("wc").checked??false)?"1":"0"}`);
},

correctAnim = [
	{	background: "var(--green2)",
		outlineColor: "var(--green5)",
		color: "var(--green6)"
	},
	{}
],

correctTiming = {
	duration: 500,
	iterations: 1
},

EL_AW = e("aw"); // written answer text box (ELement Answer Written)

let
OBJ_DATA = [],
ANS, // answer strings to match to determine if the user has answered
cg = {}, // game constants
cv = { // game variables
	active: false
},
conf = {
	zoom: 1.5,
	cookies: false,
	mapDisplay: 3
},
nsg, // function that normalizes the string based on the configuration
gs = Array.from({ length: TYPES.length }, () => []); // group selection: contains all the types with their respective objects

// unpack objects
OBJ_SRC.split("&").forEach((k, i) => {
	const
	a = k.split(":"),
	pos = parseInt(a[0].substring(1, 4), 36) ?? 0,
	x = pos % 200,
	type = parseInt(a[0][0], 36);

	let
	path = a[1];

	if (path[0] == "=") {
		path = parseInt(path.substring(1));
	}

	OBJ_DATA.push({
		type: type,
		x: x/2,
		y: Math.round(0.005 * (pos-x)) / 2,
		path: path,

		names: a[0].substring(4).split(";").map(m => {
			return [m.split("|")[0], m.replaceAll("|", "")];
		})
	});

	gs[type].push(i);
});

// initialize config
(() => {
	const
	s = getCookie("s"),
	o = getCookie("o");

	if (s === null) {
		conf.selected = new Array(OBJ_DATA.length).fill(true);
		e("ce").checked = false;
		return;
	}

	conf.cookies = true;
	e("ce").checked = true;

	// the below parses the selected object string
	const l = Math.ceil(OBJ_DATA.length/5);

	conf.selected = s.substring(0, l) // substring of the selected objects string
		.split("")					// to chars
		.map(c => {					// the chars are mapped to boolean arrays [bool; 5]
			return parseInt(c, 32)	// from b32
				.toString(2)		// to binary string
				.padStart(5, "0")	// padded
				.split("")			// it's characters
				.map(b => {			// mapped as booleans
						return b=="0"
							? false
							: true;
					}
				);					// (end of return expression)
		})
		.flat()						// flattened
		.slice(0, OBJ_DATA.length);	// trimmed

	e("wd").checked = o[0]==1;
	e("wc").checked = o[1]==1;
})()

document.addEventListener("keydown", keyD, false);

{	const
	s = e("sel"),
	l = TYPES.length;

	s.innerHTML = `<div class="h"><h1>Valik</h1><button onmousedown="selGr(null,true)">Vali kõik</button><button onmousedown="selGr(null,false)">Tühista kõik</button></div>`;

	for (let i = 0; i < l; i++) {
		const
		g = gs[i],
		n = gs.length;

		// handle blank type groups
		if (n < 1) {
			continue;
		}

		const
		head = document.createElement("div"),
		cont = document.createElement("div"),
		t = document.createElement("h2");

		head.classList.add("h");
		cont.classList.add("g");

		t.innerText = TYPES[i][1];

		head.appendChild(t);
		head.innerHTML += `<button onclick="selGr(${i},true)">Vali kõik</button><button onclick="selGr(${i},false)">Tühista kõik</button>`;

		g.forEach(k => {
			const p = document.createElement("button");

			p.dataset.i = k;
			p.addEventListener("click", sel);
			p.innerText = OBJ_DATA[k].names[0][1];
			p.tabIndex = 0;
			p.id = `s${k}`;

			if (conf.selected[k]) {
				p.classList.add("s");
			}

			cont.appendChild(p);
		});

		s.appendChild(head);
		s.appendChild(cont);
	}
}

